            } else if (dist <= riverWidth) {
              // River bank: mud/beach, but preserve some rocky areas
              if (t !== TILE_WATER_DEEP && t !== TILE_WATER && t !== TILE_WATER_DEEP) {
                const bankChoice = perlin2(tx * 0.15, ty * 0.15, perm);
                if (bankChoice > 0.4) {
