function findChestDropTile(chunks, chest) {
  if (!chest) return null;
  for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const nx = chest.x + dx;
    const ny = chest.y + dy;
    const t = getWorldTile(chunks, nx, ny);
    if (t === TILE_FLOOR || t === TILE_DOOR) return { x: nx, y: ny };
  }
