Deno.test("sleep schedule ignores controlled pets", () => {
  const world = new World({ seed: 0x7A4ED });
  world.step = NINE_PM;
  const bear = spawnMonsterEntity(world, {
    identity: "cave_bear",
    sleep: false,
  });
  world.add(bear, Pet);
  world.set(bear, AggroState, { alertLevel: AGGRO_LEVELS.unaware });

  let slept = null;
  world.on("sleep:slept", (ev) => {
    slept = ev;
  });
  sleepScheduleSystem(world);

  assert(
    !isAsleep(world, bear),
    "controlled pets should not enter authored sleep cycles",
  );
  assertEquals(slept, null);
});

Deno.test("sleep schedule can put unaware cave bear to sleep at night", () => {
  const world = new World({ seed: 0xBED });
  world.step = NINE_PM;
  const bear = spawnMonsterEntity(world, {
    identity: "cave_bear",
    sleep: false,
  });
  world.set(bear, AggroState, { alertLevel: AGGRO_LEVELS.unaware });

  let slept = null;
  world.on("sleep:slept", (ev) => {
    slept = ev;
  });
  sleepScheduleSystem(world);

  assert(
    isAsleep(world, bear),
    "unaware cave bear should fall asleep during night rest phase",
  );
  assertEquals(slept?.actor, bear);
  assertEquals(slept?.reason, "scheduled_rest");
});

