function ensureCarryInventory(world, id) {
  const inv = world.get(id, Inventory);
  if (!inv) {
    world.add(id, Inventory, { capacity: 6 });
    return;
  }
  if (Number(inv.capacity || 0) < 4) {
    world.set(id, Inventory, { ...inv, capacity: 6 });
  }
}

