function handleReturning(world, id, pos, job) {
  if (nearPoint(pos, job.homeX, job.homeY, 2)) {
    setIdle(job, world);
    if (job.carrying) world.emit("townfolk:delivered", { actor: id, resource: job.carrying });
    job.carrying = "";
    job.carryCount = 0;
    return;
  }

